using System;using System.Collections.Generic;using UnityEditor;using UnityEngine;using IdleRestaurant;
public static class RestaurantPeopleAuthoring{
 [MenuItem("Restaurant/Production/Bake varied people")]
 public static void Run(){if(EditorApplication.isPlaying)throw new Exception("Stop Play mode first");string dir="Assets/Restaurant/Production/Art/People";System.IO.Directory.CreateDirectory(dir);AssetDatabase.Refresh();var catalog=AssetDatabase.LoadAssetAtPath<RestaurantCatalog>(RestaurantProductionBuilder.CatalogPath);var path=dir+"/PeopleGeometry.asset";var bundle=AssetDatabase.LoadAssetAtPath<RestaurantArtBundle>(path);if(!bundle){bundle=ScriptableObject.CreateInstance<RestaurantArtBundle>();AssetDatabase.CreateAsset(bundle,path);}var added=new HashSet<UnityEngine.Object>();catalog.guestVariants=Bake(0,12,dir,bundle,added);catalog.chefVariants=Bake(1,6,dir,bundle,added);catalog.hostVariants=Bake(2,6,dir,bundle,added);catalog.janitorVariants=Bake(3,2,dir,bundle,added);EditorUtility.SetDirty(catalog);AssetDatabase.SaveAssets();Debug.Log("BAKED_PEOPLE 12 guests, 6 chefs, 6 hosts, 2 janitors");}
 static GameObject[] Bake(int role,int count,string dir,RestaurantArtBundle bundle,HashSet<UnityEngine.Object> added){var result=new GameObject[count];string name=new[]{"Guest","Chef","Host","Janitor"}[role];for(int i=0;i<count;i++){var holder=new GameObject("People authoring");var p=RestaurantCharacterArt.Create(holder.transform,Vector3.zero,role==3?i*3:i,role);p.root.name=name+" appearance "+i;var rig=p.root.gameObject.AddComponent<RestaurantActorRig>();rig.body=p.body;rig.head=p.head;rig.leftArm=p.leftArm;rig.rightArm=p.rightArm;rig.leftLeg=p.leftLeg;rig.rightLeg=p.rightLeg;rig.leftKnee=p.leftKnee;rig.rightKnee=p.rightKnee;rig.tray=p.tray;foreach(var f in p.root.GetComponentsInChildren<MeshFilter>(true))if(f.sharedMesh&&!AssetDatabase.Contains(f.sharedMesh)&&added.Add(f.sharedMesh))AssetDatabase.AddObjectToAsset(f.sharedMesh,bundle);foreach(var r in p.root.GetComponentsInChildren<Renderer>(true))foreach(var mat in r.sharedMaterials)if(mat&&!AssetDatabase.Contains(mat)&&added.Add(mat))AssetDatabase.AddObjectToAsset(mat,bundle);AssetDatabase.SaveAssets();result[i]=PrefabUtility.SaveAsPrefabAsset(p.root.gameObject,dir+"/"+name+i.ToString("00")+".prefab");UnityEngine.Object.DestroyImmediate(holder);}return result;}
}
